 46→/**
 47→ * Wraps native fetch to work around grammY's polyfilled AbortController.
 48→ * grammY uses abort-controller polyfill whose AbortSignal fails instanceof
 49→ * checks in Node 24+ native fetch. This wrapper re-creates a native
 50→ * AbortSignal from the polyfilled one before passing it to fetch.
 51→ */
 52→function patchedFetch(
 53→  input: RequestInfo | URL,
 54→  init?: RequestInit,
 55→): Promise<Response> {
 56→  if (init?.signal && !(init.signal instanceof AbortSignal)) {
 57→    const nativeController = new AbortController();
 58→    const polyfillSignal = init.signal as unknown as {
 59→      aborted: boolean;
 60→      addEventListener: (event: string, fn: () => void) => void;
 61→    };
 62→    if (polyfillSignal.aborted) {
 63→      nativeController.abort();
 64→    } else {
 65→      polyfillSignal.addEventListener("abort", () => nativeController.abort());
 66→    }
 67→    init = { ...init, signal: nativeController.signal };
 68→  }
 69→  return fetch(input, init);
 70→}
