418→  // --- ChannelAdapter implementations ---
419→
420→  async sendMessage(
421→    sessionId: string,
422→    content: OutgoingMessage,
423→  ): Promise<void> {
424→    // Suppress assistant messages during system prompt
425→    if (this.assistantInitializing && sessionId === this.assistantSession?.id) return;
426→
427→    const session = this.core.sessionManager.getSession(sessionId);
428→    if (!session) return;
429→    const threadId = Number(session.threadId);
430→    if (!threadId || isNaN(threadId)) {
431→      log.warn({ sessionId, threadId: session.threadId }, "Session has no valid threadId, skipping message");
432→      return;
433→    }
434→
435→    switch (content.type) {
436→      case "thought": {
437→        const tracker = this.getOrCreateTracker(sessionId, threadId);
438→        await tracker.onThought();
439→        break;
440→      }
441→
442→      case "text": {
443→        if (!this.draftManager.hasDraft(sessionId)) {
444→          const tracker = this.getOrCreateTracker(sessionId, threadId);
445→          await tracker.onTextStart();
446→        }
447→        const draft = this.draftManager.getOrCreate(sessionId, threadId);
448→        draft.append(content.text);
449→        this.draftManager.appendText(sessionId, content.text);
450→        break;
451→      }
452→
453→      case "tool_call": {
454→        const tracker = this.getOrCreateTracker(sessionId, threadId);
455→        await tracker.onToolCall();
456→        await this.draftManager.finalize(sessionId, this.assistantSession?.id);
457→        const meta = content.metadata as never as {
458→          id: string;
459→          name: string;
460→          kind?: string;
461→          status?: string;
462→          content?: unknown;
463→          viewerLinks?: { file?: string; diff?: string };
464→        };
465→        await this.toolTracker.trackNewCall(sessionId, threadId, {
466→          ...meta,
467→          viewerFilePath: (content.metadata as any)?.viewerFilePath,
468→        });
469→        break;
470→      }
471→
472→      case "tool_update": {
473→        const meta = content.metadata as never as {
474→          id: string;
475→          name: string;
476→          kind?: string;
477→          status: string;
478→          content?: unknown;
479→          viewerLinks?: { file?: string; diff?: string };
480→        };
481→        await this.toolTracker.updateCall(sessionId, {
482→          ...meta,
483→          viewerFilePath: (content.metadata as any)?.viewerFilePath,
484→        });
485→        break;
486→      }
487→
488→      case "plan": {
489→        const meta = content.metadata as never as {
490→          entries: Array<{ content: string; status: string; priority: string }>;
491→        };
492→        const tracker = this.getOrCreateTracker(sessionId, threadId);
493→        await tracker.onPlan(
494→          meta.entries.map(e => ({
495→            content: e.content,
496→            status: e.status as 'pending' | 'in_progress' | 'completed',
497→            priority: (e.priority ?? 'medium') as 'high' | 'medium' | 'low',
498→          })),
499→        );
500→        break;
501→      }
502→
503→      case "usage": {
504→        const meta = content.metadata as never as {
505→          tokensUsed?: number;
506→          contextSize?: number;
507→        };
508→        await this.draftManager.finalize(sessionId, this.assistantSession?.id);
509→        const tracker = this.getOrCreateTracker(sessionId, threadId);
510→        await tracker.sendUsage(meta);
511→
512→        // Notify the Notifications topic that a prompt has completed
513→        if (this.notificationTopicId && sessionId !== this.assistantSession?.id) {
514→          const sess = this.core.sessionManager.getSession(sessionId);
515→          const sessionName = sess?.name || 'Session';
516→          const chatIdStr = String(this.telegramConfig.chatId);
517→          const numericId = chatIdStr.startsWith('-100') ? chatIdStr.slice(4) : chatIdStr.replace('-', '');
518→          const usageMsgId = tracker.getUsageMsgId();
519→          const deepLink = `https://t.me/c/${numericId}/${usageMsgId ?? threadId}`;
520→          const text = `✅ <b>${escapeHtml(sessionName)}</b>\nTask completed.\n\n<a href="${deepLink}">→ Go to topic</a>`;
521→          this.sendQueue.enqueue(() =>
522→            this.bot.api.sendMessage(this.telegramConfig.chatId, text, {
523→              message_thread_id: this.notificationTopicId,
524→              parse_mode: 'HTML',
525→              disable_notification: false,
526→            }),
527→          ).catch(() => {});
528→        }
529→        break;
530→      }
531→
532→      case "session_end": {
533→        await this.draftManager.finalize(sessionId, this.assistantSession?.id);
534→        this.draftManager.cleanup(sessionId);
535→        this.toolTracker.cleanup(sessionId);
536→        await this.skillManager.cleanup(sessionId);
537→        const tracker = this.sessionTrackers.get(sessionId);
538→        if (tracker) {
539→          await tracker.onComplete();
540→          tracker.destroy();
541→          this.sessionTrackers.delete(sessionId);
542→        } else {
543→          await this.sendQueue.enqueue(() =>
544→            this.bot.api.sendMessage(
545→              this.telegramConfig.chatId,
546→              `✅ <b>Done</b>`,
547→              {
548→                message_thread_id: threadId,
549→                parse_mode: "HTML",
550→                disable_notification: true,
551→              },
552→            ),
553→          );
554→        }
555→        break;
556→      }
557→
558→      case "error": {
559→        await this.draftManager.finalize(sessionId, this.assistantSession?.id);
560→        const tracker = this.sessionTrackers.get(sessionId);
561→        if (tracker) {
562→          tracker.destroy();
563→          this.sessionTrackers.delete(sessionId);
564→        }
565→        await this.sendQueue.enqueue(() =>
566→          this.bot.api.sendMessage(
567→            this.telegramConfig.chatId,
568→            `❌ <b>Error:</b> ${escapeHtml(content.text)}`,
569→            {
570→              message_thread_id: threadId,
571→              parse_mode: "HTML",
572→              disable_notification: true,
573→            },
574→          ),
575→        );
576→        break;
577→      }
578→    }
579→  }
580→
581→  async sendPermissionRequest(
582→    sessionId: string,
583→    request: PermissionRequest,
584→  ): Promise<void> {
585→    log.info({ sessionId, requestId: request.id }, "Permission request sent");
586→    const session = this.core.sessionManager.getSession(sessionId);
587→    if (!session) return;
588→
589→    // Auto-approve openacp CLI commands
590→    if (request.description.includes("openacp")) {
591→      const allowOption = request.options.find((o) => o.isAllow);
592→      if (allowOption && session.permissionGate.requestId === request.id) {
593→        log.info({ sessionId, requestId: request.id }, "Auto-approving openacp command");
594→        session.permissionGate.resolve(allowOption.id);
595→      }
596→      return;
597→    }
598→
599→    // Dangerous mode: auto-approve
600→    if (session.dangerousMode) {
601→      const allowOption = request.options.find((o) => o.isAllow);
602→      if (allowOption && session.permissionGate.requestId === request.id) {
603→        log.info({ sessionId, requestId: request.id, optionId: allowOption.id }, "Dangerous mode: auto-approving permission");
604→        session.permissionGate.resolve(allowOption.id);
605→      }
606→      return;
607→    }
608→
609→    await this.sendQueue.enqueue(() =>
610→      this.permissionHandler.sendPermissionRequest(session, request),
611→    );
612→  }
613→
614→  async sendNotification(notification: NotificationMessage): Promise<void> {
615→    if (notification.sessionId === this.assistantSession?.id) return;
616→
617→    log.info(
618→      { sessionId: notification.sessionId, type: notification.type },
619→      "Notification sent",
620→    );
621→    if (!this.notificationTopicId) return;
622→    const emoji: Record<string, string> = {
623→      completed: "✅",
624→      error: "❌",
625→      permission: "🔐",
626→      input_required: "💬",
627→    };
628→    let text = `${emoji[notification.type] || "ℹ️"} <b>${escapeHtml(notification.sessionName || "New session")}</b>\n`;
629→    text += escapeHtml(notification.summary);
630→
631→    const deepLink = notification.deepLink ?? (() => {
632→      const session = this.core.sessionManager.getSession(notification.sessionId);
633→      const threadId = session?.threadId;
634→      if (!threadId) return undefined;
635→      const chatIdStr = String(this.telegramConfig.chatId);
636→      const numericId = chatIdStr.startsWith("-100") ? chatIdStr.slice(4) : chatIdStr.replace("-", "");
637→      return `https://t.me/c/${numericId}/${threadId}`;
638→    })();
639→
640→    if (deepLink) {
641→      text += `\n\n<a href="${deepLink}">→ Go to topic</a>`;
642→    }
643→    await this.sendQueue.enqueue(() =>
644→      this.bot.api.sendMessage(this.telegramConfig.chatId, text, {
645→        message_thread_id: this.notificationTopicId,
646→        parse_mode: "HTML",
647→        disable_notification: false,
648→      }),
649→    );
650→  }
651→
652→  async createSessionThread(sessionId: string, name: string): Promise<string> {
653→    log.info({ sessionId, name }, "Session topic created");
654→    return String(
655→      await createSessionTopic(this.bot, this.telegramConfig.chatId, name),
656→    );
657→  }
658→
659→  async renameSessionThread(sessionId: string, newName: string): Promise<void> {
660→    const session = this.core.sessionManager.getSession(sessionId);
661→    if (!session) return;
662→    await renameSessionTopic(
663→      this.bot,
664→      this.telegramConfig.chatId,
665→      Number(session.threadId),
666→      newName,
667→    );
668→    await this.core.sessionManager.patchRecord(sessionId, { name: newName });
669→  }
670→
671→  async deleteSessionThread(sessionId: string): Promise<void> {
672→    const record = this.core.sessionManager.getSessionRecord(sessionId);
673→    const platform = record?.platform as import("../../core/types.js").TelegramPlatformData | undefined;
674→    const topicId = platform?.topicId;
675→    if (!topicId) return;
676→
677→    try {
678→      await this.bot.api.deleteForumTopic(this.telegramConfig.chatId, topicId);
679→    } catch (err) {
680→      log.warn({ err, sessionId, topicId }, "Failed to delete forum topic (may already be deleted)");
681→    }
682→  }
683→
684→  async sendSkillCommands(
685→    sessionId: string,
686→    commands: AgentCommand[],
687→  ): Promise<void> {
688→    if (sessionId === this.assistantSession?.id) return;
689→
690→    const session = this.core.sessionManager.getSession(sessionId);
691→    if (!session) return;
692→    const threadId = Number(session.threadId);
693→    if (!threadId) return;
694→
695→    await this.skillManager.send(sessionId, threadId, commands);
696→  }
697→
698→  async cleanupSkillCommands(sessionId: string): Promise<void> {
699→    await this.skillManager.cleanup(sessionId);
700→  }
701→}
