 12→interface PendingNewSession {
 13→  agentName?: string;
 14→  workspace?: string;
 15→  step: "agent" | "workspace" | "workspace_input" | "confirm";
 16→  messageId: number;
 17→  threadId?: number;
 18→  timer: ReturnType<typeof setTimeout>;
 19→}
 20→
 21→const pendingNewSessions = new Map<number, PendingNewSession>();
 22→
 23→const PENDING_TIMEOUT_MS = 5 * 60 * 1000; // 5 minutes
 24→
 25→function cleanupPending(userId: number): void {
 26→  const pending = pendingNewSessions.get(userId);
 27→  if (pending) {
 28→    clearTimeout(pending.timer);
 29→    pendingNewSessions.delete(userId);
 30→  }
 31→}
