 38→export async function handleNew(
 39→  ctx: Context,
 40→  core: OpenACPCore,
 41→  chatId: number,
 42→  assistant?: CommandsAssistantContext,
 43→): Promise<void> {
 44→  const rawMatch = (ctx as Context & { match: unknown }).match;
 45→  const matchStr = typeof rawMatch === "string" ? rawMatch : "";
 46→  const args = matchStr.split(" ").filter(Boolean);
 47→  const agentName = args[0];
 48→  const workspace = args[1];
 49→
 50→  // Full args → create directly
 51→  if (agentName && workspace) {
 52→    await createSessionDirect(ctx, core, chatId, agentName, workspace);
 53→    return;
 54→  }
 55→
 56→  // In assistant topic → forward to assistant for conversational handling
 57→  const currentThreadId = ctx.message?.message_thread_id;
 58→  if (assistant && currentThreadId === assistant.topicId) {
 59→    const assistantSession = assistant.getSession();
 60→    if (assistantSession) {
 61→      const prompt = agentName
 62→        ? `User wants to create a new session with agent "${agentName}" but didn't specify a workspace. Ask them which project directory to use as workspace.`
 63→        : `User wants to create a new session. Guide them through choosing an agent and workspace (project directory).`;
 64→      await assistantSession.enqueuePrompt(prompt);
 65→      return;
 66→    }
 67→  }
 68→
 69→  // Outside assistant topic → interactive agent picker flow
 70→  await showAgentPicker(ctx, core, chatId, agentName);
 71→}
