 73→async function startWorkspaceStep(
 74→  ctx: Context,
 75→  core: OpenACPCore,
 76→  chatId: number,
 77→  userId: number,
 78→  agentName: string,
 79→): Promise<void> {
 80→  const config = core.configManager.get();
 81→  const baseDir = config.workspace.baseDir;
 82→
 83→  const keyboard = new InlineKeyboard()
 84→    .text(`📁 Use ${baseDir}`, "m:new:ws:default")
 85→    .row()
 86→    .text("✏️ Enter project path", "m:new:ws:custom");
 87→
 88→  const text =
 89→    `📁 <b>Where should ${escapeHtml(agentName)} work?</b>\n\n` +
 90→    `Enter the path to your project folder — the agent will read, write, and run code there.\n\n` +
 91→    `Or use the default directory below:`;
 92→
 93→  let msg;
 94→  try {
 95→    const pending = pendingNewSessions.get(userId);
 96→    if (pending?.messageId) {
 97→      await ctx.api.editMessageText(chatId, pending.messageId, text, {
 98→        parse_mode: "HTML",
 99→        reply_markup: keyboard,
100→      });
101→      msg = { message_id: pending.messageId };
102→    } else {
103→      msg = await ctx.reply(text, { parse_mode: "HTML", reply_markup: keyboard });
104→    }
105→  } catch {
106→    msg = await ctx.reply(text, { parse_mode: "HTML", reply_markup: keyboard });
107→  }
108→
109→  cleanupPending(userId);
110→  pendingNewSessions.set(userId, {
111→    agentName,
112→    step: "workspace",
113→    messageId: msg.message_id,
114→    threadId: ctx.message?.message_thread_id ?? (ctx.callbackQuery as any)?.message?.message_thread_id,
115→    timer: setTimeout(() => pendingNewSessions.delete(userId), PENDING_TIMEOUT_MS),
116→  });
117→}
