217→export async function handleNewChat(
218→  ctx: Context,
219→  core: OpenACPCore,
220→  chatId: number,
221→): Promise<void> {
222→  const threadId = ctx.message?.message_thread_id;
223→  if (!threadId) {
224→    await ctx.reply(
225→      "Use /newchat inside a session topic to inherit its config.",
226→      { parse_mode: "HTML" },
227→    );
228→    return;
229→  }
230→
231→  // Resolve agent config from existing session/record BEFORE spawning
232→  const currentSession = core.sessionManager.getSessionByThread(
233→    "telegram",
234→    String(threadId),
235→  );
236→  let agentName: string | undefined;
237→  let workspace: string | undefined;
238→
239→  if (currentSession) {
240→    agentName = currentSession.agentName;
241→    workspace = currentSession.workingDirectory;
242→  } else {
243→    const record = core.sessionManager.getRecordByThread("telegram", String(threadId));
244→    if (!record || record.status === "cancelled" || record.status === "error") {
245→      await ctx.reply("No active session in this topic.", {
246→        parse_mode: "HTML",
247→      });
248→      return;
249→    }
250→    agentName = record.agentName;
251→    workspace = record.workingDir;
252→  }
253→
254→  let newThreadId: number | undefined;
255→  try {
256→    // Create topic FIRST so threadId is ready before session events fire
257→    const topicName = `🔄 ${agentName} — New Chat`;
258→    newThreadId = await createSessionTopic(
259→      botFromCtx(ctx),
260→      chatId,
261→      topicName,
262→    );
263→
264→    // Notify in the original topic immediately with a deep link to the new one
265→    const topicLink = buildDeepLink(chatId, newThreadId);
266→    await ctx.reply(
267→      `✅ New chat created → <a href="${topicLink}">Open topic</a>`,
268→      { parse_mode: "HTML" },
269→    );
270→
271→    await ctx.api.sendMessage(chatId, `⏳ Setting up session, please wait...`, {
272→      message_thread_id: newThreadId,
273→      parse_mode: "HTML",
274→    });
275→
276→    const session = await core.handleNewSession(
277→      "telegram",
278→      agentName,
279→      workspace,
280→    );
281→    session.threadId = String(newThreadId);
282→
283→    // Persist platform mapping for new chat
284→    await core.sessionManager.patchRecord(session.id, { platform: {
285→      topicId: newThreadId,
286→    } });
287→
288→    await ctx.api.sendMessage(
289→      chatId,
290→      `✅ New chat (same agent &amp; workspace)\n` +
291→        `<b>Agent:</b> ${escapeHtml(session.agentName)}\n` +
292→        `<b>Workspace:</b> <code>${escapeHtml(session.workingDirectory)}</code>`,
293→      {
294→        message_thread_id: newThreadId,
295→        parse_mode: "HTML",
296→        reply_markup: buildDangerousModeKeyboard(session.id, false),
297→      },
298→    );
299→
300→    // Warm up model cache in background while user types
301→    session.warmup().catch((err) => log.error({ err }, "Warm-up error"));
302→  } catch (err) {
303→    // Clean up orphaned topic if session creation failed
304→    if (newThreadId) {
305→      try {
306→        await ctx.api.deleteForumTopic(chatId, newThreadId);
307→      } catch {
308→        /* ignore cleanup failures */
309→      }
310→    }
311→    const message = err instanceof Error ? err.message : String(err);
312→    await ctx.reply(`❌ ${escapeHtml(message)}`, { parse_mode: "HTML" });
313→  }
314→}
