364→/**
365→ * Check if a text message is a workspace path input for the interactive new session flow.
366→ * Returns true if the message was handled (caller should not process further).
367→ */
368→export async function handlePendingWorkspaceInput(
369→  ctx: Context,
370→  core: OpenACPCore,
371→  chatId: number,
372→  assistantTopicId?: number,
373→): Promise<boolean> {
374→  const userId = ctx.from?.id;
375→  if (!userId) return false;
376→  const pending = pendingNewSessions.get(userId);
377→  if (!pending || !ctx.message?.text) return false;
378→  // Accept text input at both "workspace" step (user types directly instead of pressing buttons)
379→  // and "workspace_input" step (user pressed "Custom path" button)
380→  if (pending.step !== "workspace_input" && pending.step !== "workspace") return false;
381→
382→  // Only intercept in assistant topic (or no-thread/general) — never in session topics
383→  const threadId = ctx.message.message_thread_id;
384→  if (threadId && threadId !== assistantTopicId) return false;
385→
386→  let workspace = ctx.message.text.trim();
387→  if (!workspace || !pending.agentName) {
388→    await ctx.reply("⚠️ Please enter a valid directory path.", { parse_mode: "HTML" });
389→    return true;
390→  }
391→
392→  // Relative path (no / or ~ prefix) → resolve against baseDir
393→  if (!workspace.startsWith("/") && !workspace.startsWith("~")) {
394→    const baseDir = core.configManager.get().workspace.baseDir;
395→    workspace = `${baseDir.replace(/\/$/, "")}/${workspace}`;
396→  }
397→
398→  await startConfirmStep(ctx, chatId, userId, pending.agentName, workspace);
399→  return true;
400→}
