415→/**
416→ * Shared agent picker logic used by both handleNew and startInteractiveNewSession.
417→ * Shows agent selection keyboard if multiple agents installed, otherwise skips to workspace step.
418→ */
419→async function showAgentPicker(
420→  ctx: Context,
421→  core: OpenACPCore,
422→  chatId: number,
423→  agentName?: string,
424→): Promise<void> {
425→  const userId = ctx.from?.id;
426→  if (!userId) return;
427→
428→  const installedEntries = core.agentCatalog.getInstalledEntries();
429→  const agentKeys = Object.keys(installedEntries);
430→  const config = core.configManager.get();
431→
432→  // If agent provided or only 1 agent → skip to workspace step
433→  if (agentName || agentKeys.length === 1) {
434→    const selectedAgent = agentName || config.defaultAgent;
435→    await startWorkspaceStep(ctx, core, chatId, userId, selectedAgent);
436→    return;
437→  }
438→
439→  // Multiple agents → show agent selection
440→  const keyboard = new InlineKeyboard();
441→  for (const key of agentKeys) {
442→    const agent = installedEntries[key]!;
443→    const label = key === config.defaultAgent
444→      ? `${agent.name} (default)`
445→      : agent.name;
446→    keyboard.text(label, `m:new:agent:${key}`).row();
447→  }
448→
449→  const msg = await ctx.reply(
450→    `🤖 <b>Choose an agent:</b>`,
451→    { parse_mode: "HTML", reply_markup: keyboard },
452→  );
453→
454→  cleanupPending(userId);
455→  const threadId = ctx.message?.message_thread_id
456→    ?? (ctx.callbackQuery as any)?.message?.message_thread_id;
457→  pendingNewSessions.set(userId, {
458→    step: "agent",
459→    messageId: msg.message_id,
460→    threadId,
461→    timer: setTimeout(() => pendingNewSessions.delete(userId), PENDING_TIMEOUT_MS),
462→  });
463→}
