465→export function setupNewSessionCallbacks(
466→  bot: Bot,
467→  core: OpenACPCore,
468→  chatId: number,
469→): void {
470→  bot.callbackQuery(/^m:new:/, async (ctx) => {
471→    const data = ctx.callbackQuery.data;
472→    try {
473→      await ctx.answerCallbackQuery();
474→    } catch { /* expired or network — ignore */ }
475→
476→    if (data.startsWith("m:new:agent:")) {
477→      const agentName = data.replace("m:new:agent:", "");
478→      const userId = ctx.from?.id;
479→      if (userId) await startWorkspaceStep(ctx, core, chatId, userId, agentName);
480→      return;
481→    }
482→    if (data === "m:new:ws:default") {
483→      const userId = ctx.from?.id;
484→      if (!userId) return;
485→      const pending = pendingNewSessions.get(userId);
486→      if (!pending?.agentName) return;
487→      const workspace = core.configManager.get().workspace.baseDir;
488→      await startConfirmStep(ctx, chatId, userId, pending.agentName, workspace);
489→      return;
490→    }
491→    if (data === "m:new:ws:custom") {
492→      const userId = ctx.from?.id;
493→      if (!userId) return;
494→      const pending = pendingNewSessions.get(userId);
495→      if (!pending?.agentName) return;
496→      try {
497→        await ctx.api.editMessageText(
498→          chatId,
499→          pending.messageId,
500→          `✏️ <b>Enter your project path:</b>\n\n` +
501→            `Full path like <code>~/code/my-project</code>\n` +
502→            `Or just the folder name like <code>my-project</code> (will use ${core.configManager.get().workspace.baseDir}/)`,
503→          { parse_mode: "HTML" },
504→        );
505→      } catch {
506→        await ctx.reply(
507→          `✏️ <b>Enter your project path:</b>`,
508→          { parse_mode: "HTML" },
509→        );
510→      }
511→      clearTimeout(pending.timer);
512→      pending.step = "workspace_input";
513→      pending.timer = setTimeout(() => pendingNewSessions.delete(userId), PENDING_TIMEOUT_MS);
514→      return;
515→    }
516→    if (data === "m:new:confirm") {
517→      const userId = ctx.from?.id;
518→      if (!userId) return;
519→      const pending = pendingNewSessions.get(userId);
520→      if (!pending?.agentName || !pending?.workspace) return;
521→      cleanupPending(userId);
522→      const confirmMsgId = pending.messageId;
523→      try {
524→        await ctx.api.editMessageText(chatId, confirmMsgId, `⏳ Creating session...`, { parse_mode: "HTML" });
525→      } catch { /* ignore */ }
526→      const resultThreadId = await createSessionDirect(ctx, core, chatId, pending.agentName, pending.workspace);
527→      try {
528→        if (resultThreadId) {
529→          const link = buildDeepLink(chatId, resultThreadId);
530→          await ctx.api.editMessageText(chatId, confirmMsgId, `✅ Session created → <a href="${link}">Open topic</a>`, { parse_mode: "HTML" });
531→        } else {
532→          await ctx.api.editMessageText(chatId, confirmMsgId, `❌ Session creation failed.`, { parse_mode: "HTML" });
533→        }
534→      } catch { /* ignore */ }
535→      return;
536→    }
537→    if (data === "m:new:cancel") {
538→      const userId = ctx.from?.id;
539→      if (userId) cleanupPending(userId);
540→      try {
541→        await ctx.editMessageText("❌ Session creation cancelled.", { parse_mode: "HTML" });
542→      } catch { /* ignore */ }
543→      return;
544→    }
545→  });
546→}
