 22→
 23→/** Find the nearest ancestor directory containing package.json */
 24→function findPackageRoot(startDir: string): string {
 25→  let dir = startDir;
 26→  while (dir !== path.dirname(dir)) {
 27→    if (fs.existsSync(path.join(dir, "package.json"))) {
 28→      return dir;
 29→    }
 30→    dir = path.dirname(dir);
 31→  }
 32→  return startDir;
 33→}
 34→
 35→/** Resolve an agent command to a directly executable form (avoids shell wrappers) */
 36→function resolveAgentCommand(cmd: string): { command: string; args: string[] } {
 37→  // Directories to search for node_modules: cwd AND the package's own directory
 38→  const searchRoots = [process.cwd()];
 39→  // Add the directory where this package is installed (for global installs)
 40→  // Use findPackageRoot instead of hardcoded "../.." to handle both tsc (dist/core/)
 41→  // and tsup bundle (dist/) directory structures correctly
 42→  const ownDir = findPackageRoot(import.meta.dirname);
 43→  if (ownDir !== process.cwd()) {
 44→    searchRoots.push(ownDir);
 45→  }
 46→
 47→  // 1. Check node_modules for the package's actual JS entry point
 48→  for (const root of searchRoots) {
 49→    const packageDirs = [
 50→      path.resolve(root, "node_modules", "@zed-industries", cmd, "dist", "index.js"),
 51→      path.resolve(root, "node_modules", cmd, "dist", "index.js"),
 52→    ];
 53→    for (const jsPath of packageDirs) {
 54→      if (fs.existsSync(jsPath)) {
 55→        return { command: process.execPath, args: [jsPath] };
 56→      }
 57→    }
 58→  }
 59→
 60→  // 2. Check .bin — if it's a JS file with shebang, run with node directly
 61→  for (const root of searchRoots) {
 62→    const localBin = path.resolve(root, "node_modules", ".bin", cmd);
 63→    if (fs.existsSync(localBin)) {
 64→      const content = fs.readFileSync(localBin, "utf-8");
 65→      if (content.startsWith("#!/usr/bin/env node")) {
 66→        return { command: process.execPath, args: [localBin] };
 67→      }
 68→      // Shell wrapper — try to find the target JS file
 69→      const match = content.match(/"([^"]+\.js)"/);
 70→      if (match) {
 71→        const target = path.resolve(path.dirname(localBin), match[1]);
 72→        if (fs.existsSync(target)) {
 73→          return { command: process.execPath, args: [target] };
 74→        }
 75→      }
 76→    }
 77→  }
 78→
 79→  // 3. Try resolving from PATH using which
 80→  try {
 81→    const fullPath = execFileSync("which", [cmd], { encoding: "utf-8" }).trim();
 82→    if (fullPath) {
 83→      const content = fs.readFileSync(fullPath, "utf-8");
 84→      if (content.startsWith("#!/usr/bin/env node")) {
 85→        return { command: process.execPath, args: [fullPath] };
 86→      }
 87→    }
 88→  } catch {
 89→    // which failed
 90→  }
 91→
 92→  // 4. Fallback: use command as-is
 93→  return { command: cmd, args: [] };
 94→}
