 1→/**
 2→ * Serial prompt queue — ensures prompts are processed one at a time.
 3→ */
 4→export class PromptQueue {
 5→  private queue: Array<{ text: string; resolve: () => void }> = []
 6→  private processing = false
 7→
 8→  constructor(
 9→    private processor: (text: string) => Promise<void>,
10→    private onError?: (err: unknown) => void,
11→  ) {}
12→
13→  async enqueue(text: string): Promise<void> {
14→    if (this.processing) {
15→      return new Promise<void>((resolve) => {
16→        this.queue.push({ text, resolve })
17→      })
18→    }
19→    await this.process(text)
20→  }
21→
22→  private async process(text: string): Promise<void> {
23→    this.processing = true
24→    try {
25→      await this.processor(text)
26→    } catch (err) {
27→      this.onError?.(err)
28→    } finally {
29→      this.processing = false
30→      this.drainNext()
31→    }
32→  }
33→
34→  private drainNext(): void {
35→    const next = this.queue.shift()
36→    if (next) {
37→      this.process(next.text).then(next.resolve)
38→    }
39→  }
40→
41→  clear(): void {
42→    // Resolve pending promises so callers don't hang
43→    for (const item of this.queue) {
44→      item.resolve()
45→    }
46→    this.queue = []
47→  }
48→
49→  get pending(): number {
50→    return this.queue.length
51→  }
52→
53→  get isProcessing(): boolean {
54→    return this.processing
55→  }
56→}
