 68→  async start(): Promise<void> {
 69→    this.server = http.createServer((req, res) => this.handleRequest(req, res))
 70→
 71→    await new Promise<void>((resolve, reject) => {
 72→      this.server!.on('error', (err: NodeJS.ErrnoException) => {
 73→        if (err.code === 'EADDRINUSE') {
 74→          log.warn({ port: this.config.port }, 'API port in use, continuing without API server')
 75→          this.server = null
 76→          // actualPort stays 0, port file not written
 77→          resolve()
 78→        } else {
 79→          reject(err)
 80→        }
 81→      })
 82→
 83→      this.server!.listen(this.config.port, this.config.host, () => {
 84→        const addr = this.server!.address()
 85→        if (addr && typeof addr === 'object') {
 86→          this.actualPort = addr.port
 87→        }
 88→        this.writePortFile()
 89→        log.info({ host: this.config.host, port: this.actualPort }, 'API server listening')
 90→        resolve()
 91→      })
 92→    })
 93→  }
