 95→  async stop(): Promise<void> {
 96→    this.removePortFile()
 97→    if (this.server) {
 98→      await new Promise<void>((resolve) => {
 99→        this.server!.close(() => resolve())
100→      })
101→      this.server = null
102→    }
103→  }
