178→  private async handleCreateSession(req: http.IncomingMessage, res: http.ServerResponse): Promise<void> {
179→    const body = await this.readBody(req)
180→    let agent: string | undefined
181→    let workspace: string | undefined
182→
183→    if (body) {
184→      try {
185→        const parsed = JSON.parse(body)
186→        agent = parsed.agent
187→        workspace = parsed.workspace
188→      } catch {
189→        this.sendJson(res, 400, { error: 'Invalid JSON body' })
190→        return
191→      }
192→    }
193→
194→    // Check max concurrent sessions
195→    const config = this.core.configManager.get()
196→    const activeSessions = this.core.sessionManager.listSessions()
197→      .filter(s => s.status === 'active' || s.status === 'initializing')
198→    if (activeSessions.length >= config.security.maxConcurrentSessions) {
199→      this.sendJson(res, 429, {
200→        error: `Max concurrent sessions (${config.security.maxConcurrentSessions}) reached. Cancel a session first.`,
201→      })
202→      return
203→    }
204→
205→    // Use the first registered adapter (e.g. Telegram) so API sessions appear in the channel
206→    const [adapterId, adapter] = this.core.adapters.entries().next().value ?? [null, null]
207→    const channelId = adapterId ?? 'api'
208→
209→    const resolvedAgent = agent || config.defaultAgent
210→    const resolvedWorkspace = this.core.configManager.resolveWorkspace(
211→      workspace || config.agents[resolvedAgent]?.workingDirectory,
212→    )
213→
214→    const session = await this.core.createSession({
215→      channelId,
216→      agentName: resolvedAgent,
217→      workingDirectory: resolvedWorkspace,
218→      createThread: !!adapter,
219→      initialName: `🔄 ${resolvedAgent} — New Session`,
220→    })
221→
222→    // If no adapter wired events (headless), auto-approve permissions
223→    if (!adapter) {
224→      session.agentInstance.onPermissionRequest = async (request) => {
225→        const allowOption = request.options.find(o => o.isAllow)
226→        log.debug({ sessionId: session.id, permissionId: request.id, option: allowOption?.id }, 'Auto-approving permission for API session')
227→        return allowOption?.id ?? request.options[0]?.id ?? ''
228→      }
229→    }
230→
231→    // Warmup in background so session moves from 'initializing' to 'active'
232→    session.warmup().catch(err => log.warn({ err, sessionId: session.id }, 'API session warmup failed'))
233→
234→    this.sendJson(res, 200, {
235→      sessionId: session.id,
236→      agent: session.agentName,
237→      status: session.status,
238→      workspace: session.workingDirectory,
239→    })
240→  }
