537→    let parsed: { agent?: string; agentSessionId?: string; cwd?: string }
538→    try {
539→      parsed = JSON.parse(body)
540→    } catch {
541→      return this.sendJson(res, 400, { error: 'bad_request', message: 'Invalid JSON' })
542→    }
543→
544→    const { agent, agentSessionId, cwd } = parsed
