600→  private async handleCleanupTopics(req: http.IncomingMessage, res: http.ServerResponse): Promise<void> {
601→    if (!this.topicManager) { this.sendJson(res, 501, { error: 'Topic management not available' }); return }
602→    const body = await this.readBody(req)
603→    let statuses: string[] | undefined
604→    if (body) {
605→      try { statuses = JSON.parse(body).statuses } catch { /* use defaults */ }
606→    }
607→    const result = await this.topicManager.cleanup(statuses)
608→    this.sendJson(res, 200, result)
609→  }
610→
611→  private readBody(req: http.IncomingMessage): Promise<string> {
612→    return new Promise((resolve) => {
613→      let data = ''
614→      req.on('data', (chunk) => { data += chunk })
615→      req.on('end', () => resolve(data))
616→      req.on('error', () => resolve(''))
617→    })
618→  }
619→}
