  8→function findPackageJson(): string | null {
  9→  let dir = dirname(fileURLToPath(import.meta.url))
 10→  for (let i = 0; i < 5; i++) {
 11→    const candidate = join(dir, 'package.json')
 12→    if (existsSync(candidate)) return candidate
 13→    const parent = resolve(dir, '..')
 14→    if (parent === dir) break
 15→    dir = parent
 16→  }
 17→  return null
 18→}
 19→
 20→export function getCurrentVersion(): string {
 21→  try {
 22→    const pkgPath = findPackageJson()
 23→    if (!pkgPath) return '0.0.0-dev'
 24→    const pkg = JSON.parse(readFileSync(pkgPath, 'utf-8'))
 25→    return pkg.version as string
 26→  } catch {
 27→    return '0.0.0-dev'
 28→  }
 29→}
