 31→export async function getLatestVersion(): Promise<string | null> {
 32→  try {
 33→    const res = await fetch(`https://registry.npmjs.org/${NPM_PACKAGE}/latest`, {
 34→      signal: AbortSignal.timeout(5000),
 35→    })
 36→    if (!res.ok) return null
 37→    const data = (await res.json()) as { version?: string }
 38→    return data.version ?? null
 39→  } catch {
 40→    return null
 41→  }
 42→}
