 54→export async function runUpdate(): Promise<boolean> {
 55→  const { spawn } = await import('node:child_process')
 56→  return new Promise((resolve) => {
 57→    const child = spawn('npm', ['install', '-g', `${NPM_PACKAGE}@latest`], {
 58→      stdio: 'inherit',
 59→      shell: true,
 60→    })
 61→    const onSignal = () => {
 62→      child.kill('SIGTERM')
 63→      resolve(false)
 64→    }
 65→    process.on('SIGINT', onSignal)
 66→    process.on('SIGTERM', onSignal)
 67→    child.on('close', (code) => {
 68→      process.off('SIGINT', onSignal)
 69→      process.off('SIGTERM', onSignal)
 70→      resolve(code === 0)
 71→    })
 72→  })
 73→}
