119→  private async handleRequest(req: http.IncomingMessage, res: http.ServerResponse): Promise<void> {
120→    const method = req.method?.toUpperCase()
121→    const url = req.url || ''
122→
123→    try {
124→      if (method === 'POST' && url === '/api/sessions/adopt') {
125→        await this.handleAdoptSession(req, res)
126→      } else if (method === 'POST' && url === '/api/sessions') {
127→        await this.handleCreateSession(req, res)
128→      } else if (method === 'POST' && url.match(/^\/api\/sessions\/([^/]+)\/prompt$/)) {
129→        const sessionId = decodeURIComponent(url.match(/^\/api\/sessions\/([^/]+)\/prompt$/)![1])
130→        await this.handleSendPrompt(sessionId, req, res)
131→      } else if (method === 'PATCH' && url.match(/^\/api\/sessions\/([^/]+)\/dangerous$/)) {
132→        const sessionId = decodeURIComponent(url.match(/^\/api\/sessions\/([^/]+)\/dangerous$/)![1])
133→        await this.handleToggleDangerous(sessionId, req, res)
134→      } else if (method === 'GET' && url.match(/^\/api\/sessions\/([^/]+)$/)) {
135→        const sessionId = decodeURIComponent(url.match(/^\/api\/sessions\/([^/]+)$/)![1])
136→        await this.handleGetSession(sessionId, res)
137→      } else if (method === 'DELETE' && url.match(/^\/api\/sessions\/([^/]+)$/)) {
138→        const sessionId = decodeURIComponent(url.match(/^\/api\/sessions\/([^/]+)$/)![1])
139→        await this.handleCancelSession(sessionId, res)
140→      } else if (method === 'GET' && url === '/api/sessions') {
141→        await this.handleListSessions(res)
142→      } else if (method === 'GET' && url === '/api/agents') {
143→        await this.handleListAgents(res)
144→      } else if (method === 'GET' && url === '/api/health') {
145→        await this.handleHealth(res)
146→      } else if (method === 'GET' && url === '/api/version') {
147→        await this.handleVersion(res)
148→      } else if (method === 'GET' && url === '/api/config/editable') {
149→        await this.handleGetEditableConfig(res)
150→      } else if (method === 'GET' && url === '/api/config') {
151→        await this.handleGetConfig(res)
152→      } else if (method === 'PATCH' && url === '/api/config') {
153→        await this.handleUpdateConfig(req, res)
154→      } else if (method === 'GET' && url === '/api/adapters') {
155→        await this.handleListAdapters(res)
156→      } else if (method === 'GET' && url === '/api/tunnel') {
157→        await this.handleTunnelStatus(res)
158→      } else if (method === 'POST' && url === '/api/notify') {
159→        await this.handleNotify(req, res)
160→      } else if (method === 'POST' && url === '/api/restart') {
161→        await this.handleRestart(res)
162→      } else if (method === 'GET' && url.match(/^\/api\/topics(\?.*)?$/)) {
163→        await this.handleListTopics(url, res)
164→      } else if (method === 'POST' && url === '/api/topics/cleanup') {
165→        await this.handleCleanupTopics(req, res)
166→      } else if (method === 'DELETE' && url.match(/^\/api\/topics\/([^/?]+)/)) {
167→        const match = url.match(/^\/api\/topics\/([^/?]+)/)!
168→        await this.handleDeleteTopic(decodeURIComponent(match[1]), url, res)
169→      } else {
170→        this.sendJson(res, 404, { error: 'Not found' })
171→      }
172→    } catch (err) {
173→      log.error({ err }, 'API request error')
174→      this.sendJson(res, 500, { error: 'Internal server error' })
175→    }
176→  }
