380→  private async handleUpdateConfig(req: http.IncomingMessage, res: http.ServerResponse): Promise<void> {
381→    const body = await this.readBody(req)
382→    let configPath: string | undefined
383→    let value: unknown
384→
385→    if (body) {
386→      try {
387→        const parsed = JSON.parse(body)
388→        configPath = parsed.path
389→        value = parsed.value
390→      } catch {
391→        this.sendJson(res, 400, { error: 'Invalid JSON body' })
392→        return
393→      }
394→    }
395→
396→    if (!configPath) {
397→      this.sendJson(res, 400, { error: 'Missing path' })
398→      return
399→    }
400→
401→    // Pre-validate by cloning config and applying the change
402→    const currentConfig = this.core.configManager.get()
403→    const cloned = structuredClone(currentConfig) as Record<string, unknown>
404→    const parts = configPath.split('.')
405→    let target: Record<string, unknown> = cloned
406→    for (let i = 0; i < parts.length - 1; i++) {
407→      if (target[parts[i]] && typeof target[parts[i]] === 'object' && !Array.isArray(target[parts[i]])) {
408→        target = target[parts[i]] as Record<string, unknown>
409→      } else {
410→        this.sendJson(res, 400, { error: 'Invalid config path' })
411→        return
412→      }
413→    }
414→
415→    const lastKey = parts[parts.length - 1]
416→    if (!(lastKey in target)) {
417→      this.sendJson(res, 400, { error: 'Invalid config path' })
418→      return
419→    }
420→
421→    target[lastKey] = value
422→
423→    // Validate with Zod
424→    const { ConfigSchema } = await import('./config.js')
425→    const result = ConfigSchema.safeParse(cloned)
426→    if (!result.success) {
427→      this.sendJson(res, 400, {
428→        error: 'Validation failed',
429→        details: result.error.issues.map(i => ({ path: i.path.join('.'), message: i.message })),
430→      })
431→      return
432→    }
433→
434→    // Convert dot-path to nested object for save
435→    const updates: Record<string, unknown> = {}
436→    let updateTarget = updates
437→    for (let i = 0; i < parts.length - 1; i++) {
438→      updateTarget[parts[i]] = {}
439→      updateTarget = updateTarget[parts[i]] as Record<string, unknown>
440→    }
441→    updateTarget[lastKey] = value
442→
443→    await this.core.configManager.save(updates, configPath)
444→
445→    const { isHotReloadable } = await import('./config-registry.js')
446→    const needsRestart = !isHotReloadable(configPath!)
447→
448→    this.sendJson(res, 200, {
449→      ok: true,
450→      needsRestart,
451→      config: redactConfig(this.core.configManager.get()),
452→    })
453→  }
