584→  private async handleDeleteTopic(sessionId: string, url: string, res: http.ServerResponse): Promise<void> {
585→    if (!this.topicManager) { this.sendJson(res, 501, { error: 'Topic management not available' }); return }
586→    const params = new URL(url, 'http://localhost').searchParams
587→    const force = params.get('force') === 'true'
588→    const result = await this.topicManager.deleteTopic(sessionId, force ? { confirmed: true } : undefined)
589→    if (result.ok) {
