591→    } else if (result.needsConfirmation) {
592→      this.sendJson(res, 409, { error: 'Session is active', needsConfirmation: true, session: result.session })
593→    } else if (result.error === 'Cannot delete system topic') {
594→      this.sendJson(res, 403, { error: result.error })
595→    } else {
596→      this.sendJson(res, 404, { error: result.error ?? 'Not found' })
597→    }
