 47→export function generateSystemdUnit(nodePath: string, cliPath: string): string {
 48→  return `[Unit]
 49→Description=OpenACP Daemon
 50→
 51→[Service]
 52→ExecStart=${nodePath} ${cliPath} --daemon-child
 53→Restart=on-failure
 54→
 55→[Install]
 56→WantedBy=default.target
 57→`
 58→}
