 60→export function installAutoStart(logDir: string): { success: boolean; error?: string } {
 61→  if (!isAutoStartSupported()) {
 62→    return { success: false, error: 'Auto-start not supported on this platform' }
 63→  }
 64→
 65→  const nodePath = process.execPath
 66→  const cliPath = path.resolve(process.argv[1])
 67→  const resolvedLogDir = logDir.startsWith('~')
 68→    ? path.join(os.homedir(), logDir.slice(1))
 69→    : logDir
 70→
 71→  try {
 72→    if (process.platform === 'darwin') {
 73→      const plist = generateLaunchdPlist(nodePath, cliPath, resolvedLogDir)
 74→      const dir = path.dirname(LAUNCHD_PLIST_PATH)
 75→      fs.mkdirSync(dir, { recursive: true })
 76→      fs.writeFileSync(LAUNCHD_PLIST_PATH, plist)
 77→      execFileSync('launchctl', ['load', LAUNCHD_PLIST_PATH], { stdio: 'pipe' })
 78→      log.info('LaunchAgent installed')
 79→      return { success: true }
 80→    }
 81→
 82→    if (process.platform === 'linux') {
 83→      const unit = generateSystemdUnit(nodePath, cliPath)
 84→      const dir = path.dirname(SYSTEMD_SERVICE_PATH)
 85→      fs.mkdirSync(dir, { recursive: true })
 86→      fs.writeFileSync(SYSTEMD_SERVICE_PATH, unit)
 87→      execFileSync('systemctl', ['--user', 'daemon-reload'], { stdio: 'pipe' })
 88→      execFileSync('systemctl', ['--user', 'enable', 'openacp'], { stdio: 'pipe' })
 89→      log.info('systemd user service installed')
 90→      return { success: true }
 91→    }
 92→
 93→    return { success: false, error: 'Unsupported platform' }
 94→  } catch (e) {
 95→    const msg = (e as Error).message
 96→    log.error({ err: msg }, 'Failed to install auto-start')
 97→    return { success: false, error: msg }
 98→  }
 99→}
100→
101→export function uninstallAutoStart(): { success: boolean; error?: string } {
102→  if (!isAutoStartSupported()) {
103→    return { success: false, error: 'Auto-start not supported on this platform' }
104→  }
105→
106→  try {
107→    if (process.platform === 'darwin') {
108→      if (fs.existsSync(LAUNCHD_PLIST_PATH)) {
109→        try {
110→          execFileSync('launchctl', ['unload', LAUNCHD_PLIST_PATH], { stdio: 'pipe' })
111→        } catch {
112→          // may already be unloaded
113→        }
114→        fs.unlinkSync(LAUNCHD_PLIST_PATH)
115→        log.info('LaunchAgent removed')
116→      }
117→      return { success: true }
118→    }
119→
120→    if (process.platform === 'linux') {
121→      if (fs.existsSync(SYSTEMD_SERVICE_PATH)) {
122→        try {
123→          execFileSync('systemctl', ['--user', 'disable', 'openacp'], { stdio: 'pipe' })
124→        } catch {
125→          // may already be disabled
126→        }
127→        fs.unlinkSync(SYSTEMD_SERVICE_PATH)
128→        execFileSync('systemctl', ['--user', 'daemon-reload'], { stdio: 'pipe' })
129→        log.info('systemd user service removed')
130→      }
131→      return { success: true }
132→    }
133→
134→    return { success: false, error: 'Unsupported platform' }
135→  } catch (e) {
136→    const msg = (e as Error).message
137→    log.error({ err: msg }, 'Failed to uninstall auto-start')
138→    return { success: false, error: msg }
139→  }
140→}
141→
142→export function isAutoStartInstalled(): boolean {
143→  if (process.platform === 'darwin') {
144→    return fs.existsSync(LAUNCHD_PLIST_PATH)
145→  }
146→  if (process.platform === 'linux') {
147→    return fs.existsSync(SYSTEMD_SERVICE_PATH)
148→  }
149→  return false
150→}
