 20→export function getCurrentVersion(): string {
 21→  try {
 22→    const pkgPath = findPackageJson()
 23→    if (!pkgPath) return '0.0.0-dev'
 24→    const pkg = JSON.parse(readFileSync(pkgPath, 'utf-8'))
 25→    return pkg.version as string
 26→  } catch {
 27→    return '0.0.0-dev'
