 44→export function compareVersions(current: string, latest: string): -1 | 0 | 1 {
 45→  const a = current.split('.').map(Number)
 46→  const b = latest.split('.').map(Number)
 47→  for (let i = 0; i < 3; i++) {
 48→    if ((a[i] ?? 0) < (b[i] ?? 0)) return -1
 49→    if ((a[i] ?? 0) > (b[i] ?? 0)) return 1
 50→  }
 51→  return 0
 52→}
