242→  private async handleSendPrompt(sessionId: string, req: http.IncomingMessage, res: http.ServerResponse): Promise<void> {
243→    const session = this.core.sessionManager.getSession(sessionId)
244→    if (!session) {
245→      this.sendJson(res, 404, { error: `Session "${sessionId}" not found` })
246→      return
247→    }
248→
249→    if (session.status === 'cancelled' || session.status === 'finished' || session.status === 'error') {
250→      this.sendJson(res, 400, { error: `Session is ${session.status}` })
251→      return
252→    }
253→
254→    const body = await this.readBody(req)
255→    let prompt: string | undefined
256→    if (body) {
257→      try {
258→        const parsed = JSON.parse(body)
259→        prompt = parsed.prompt
260→      } catch {
261→        this.sendJson(res, 400, { error: 'Invalid JSON body' })
262→        return
263→      }
264→    }
265→
266→    if (!prompt) {
267→      this.sendJson(res, 400, { error: 'Missing prompt' })
268→      return
269→    }
270→
271→    session.enqueuePrompt(prompt).catch(() => {})
272→    this.sendJson(res, 200, { ok: true, sessionId, queueDepth: session.queueDepth })
