  1→import { spawn } from 'node:child_process'
  2→import * as fs from 'node:fs'
  3→import * as path from 'node:path'
  4→import * as os from 'node:os'
  5→import { expandHome } from './config.js'
  6→
  7→const DEFAULT_PID_PATH = path.join(os.homedir(), '.openacp', 'openacp.pid')
  8→const DEFAULT_LOG_DIR = path.join(os.homedir(), '.openacp', 'logs')
  9→const RUNNING_MARKER = path.join(os.homedir(), '.openacp', 'running')
 10→
 11→export function writePidFile(pidPath: string, pid: number): void {
 12→  const dir = path.dirname(pidPath)
 13→  fs.mkdirSync(dir, { recursive: true })
 14→  fs.writeFileSync(pidPath, String(pid))
 15→}
 16→
 17→export function readPidFile(pidPath: string): number | null {
 18→  try {
 19→    const content = fs.readFileSync(pidPath, 'utf-8').trim()
 20→    const pid = parseInt(content, 10)
 21→    return isNaN(pid) ? null : pid
 22→  } catch {
 23→    return null
 24→  }
 25→}
 26→
 27→export function removePidFile(pidPath: string): void {
 28→  try {
 29→    fs.unlinkSync(pidPath)
 30→  } catch {
 31→    // ignore if already gone
 32→  }
 33→}
 34→
 35→export function isProcessRunning(pidPath: string): boolean {
 36→  const pid = readPidFile(pidPath)
 37→  if (pid === null) return false
 38→  try {
 39→    process.kill(pid, 0)
 40→    return true
 41→  } catch {
 42→    // Process not running, clean up stale PID file
 43→    removePidFile(pidPath)
 44→    return false
 45→  }
 46→}
 47→
 48→export function getStatus(pidPath: string = DEFAULT_PID_PATH): { running: boolean; pid?: number } {
 49→  const pid = readPidFile(pidPath)
 50→  if (pid === null) return { running: false }
 51→  try {
 52→    process.kill(pid, 0)
 53→    return { running: true, pid }
 54→  } catch {
 55→    removePidFile(pidPath)
 56→    return { running: false }
 57→  }
 58→}
 59→
 60→export function startDaemon(pidPath: string = DEFAULT_PID_PATH, logDir?: string): { pid: number } | { error: string } {
 61→  // Mark as running so auto-start works on next boot
 62→  markRunning()
 63→
 64→  // Check if already running
 65→  if (isProcessRunning(pidPath)) {
 66→    const pid = readPidFile(pidPath)!
 67→    return { error: `Already running (PID ${pid})` }
 68→  }
 69→
 70→  const resolvedLogDir = logDir ? expandHome(logDir) : DEFAULT_LOG_DIR
 71→  fs.mkdirSync(resolvedLogDir, { recursive: true })
 72→  const logFile = path.join(resolvedLogDir, 'openacp.log')
 73→
 74→  // Find the CLI entry point
 75→  const cliPath = path.resolve(process.argv[1])
 76→  const nodePath = process.execPath
 77→
 78→  const out = fs.openSync(logFile, 'a')
 79→  const err = fs.openSync(logFile, 'a')
 80→
 81→  const child = spawn(nodePath, [cliPath, '--daemon-child'], {
 82→    detached: true,
 83→    stdio: ['ignore', out, err],
 84→  })
 85→
 86→  // Close file descriptors in parent — child has its own copies
 87→  fs.closeSync(out)
 88→  fs.closeSync(err)
 89→
 90→  if (!child.pid) {
 91→    return { error: 'Failed to spawn daemon process' }
 92→  }
 93→
 94→  // PID file is written by the child process itself (in main.ts startServer)
 95→  // to avoid race conditions and ensure consistency with LaunchAgent/systemd starts.
 96→  // We still write it here as a fallback in case the child hasn't written it yet
 97→  // when the parent needs to report the PID.
 98→  writePidFile(pidPath, child.pid)
 99→  child.unref()
100→
101→  return { pid: child.pid }
102→}
103→
104→export function stopDaemon(pidPath: string = DEFAULT_PID_PATH): { stopped: boolean; pid?: number; error?: string } {
105→  const pid = readPidFile(pidPath)
106→  if (pid === null) return { stopped: false, error: 'Not running (no PID file)' }
107→
108→  try {
109→    process.kill(pid, 0) // check alive
110→  } catch {
111→    removePidFile(pidPath)
112→    return { stopped: false, error: 'Not running (stale PID file removed)' }
113→  }
114→
115→  try {
116→    process.kill(pid, 'SIGTERM')
117→    // Remove running marker so auto-start won't restart on next boot
118→    clearRunning()
119→    // PID file is cleaned up by the child process on SIGTERM (see main.ts shutdown handler).
120→    // Also remove here in case child crashes before cleanup.
121→    removePidFile(pidPath)
122→    return { stopped: true, pid }
123→  } catch (e) {
124→    return { stopped: false, error: `Failed to stop: ${(e as Error).message}` }
125→  }
126→}
127→
128→export function getPidPath(): string {
129→  return DEFAULT_PID_PATH
130→}
131→
132→/** Mark that the daemon should auto-start on boot */
133→export function markRunning(): void {
134→  fs.mkdirSync(path.dirname(RUNNING_MARKER), { recursive: true })
135→  fs.writeFileSync(RUNNING_MARKER, '')
136→}
137→
138→/** Remove running marker — daemon won't auto-start on boot */
139→export function clearRunning(): void {
140→  try { fs.unlinkSync(RUNNING_MARKER) } catch { /* ignore */ }
141→}
142→
143→/** Check if the daemon was running before (should auto-start on boot) */
144→export function shouldAutoStart(): boolean {
145→  return fs.existsSync(RUNNING_MARKER)
146→}
