 31→export async function getLatestVersion(): Promise<string | null> {
 32→  try {
 33→    const res = await fetch(`https://registry.npmjs.org/${NPM_PACKAGE}/latest`, {
 34→      signal: AbortSignal.timeout(5000),
 35→    })
 36→    if (!res.ok) return null
 37→    const data = (await res.json()) as { version?: string }
 38→    return data.version ?? null
 39→  } catch {
 40→    return null
 41→  }
 42→}
 43→
 44→export function compareVersions(current: string, latest: string): -1 | 0 | 1 {
 45→  const a = current.split('.').map(Number)
 46→  const b = latest.split('.').map(Number)
 47→  for (let i = 0; i < 3; i++) {
 48→    if ((a[i] ?? 0) < (b[i] ?? 0)) return -1
 49→    if ((a[i] ?? 0) > (b[i] ?? 0)) return 1
 50→  }
 51→  return 0
 52→}
 53→
 54→export async function runUpdate(): Promise<boolean> {
 55→  const { spawn } = await import('node:child_process')
 56→  return new Promise((resolve) => {
 57→    const child = spawn('npm', ['install', '-g', `${NPM_PACKAGE}@latest`], {
 58→      stdio: 'inherit',
 59→      shell: true,
 60→    })
 61→    const onSignal = () => {
 62→      child.kill('SIGTERM')
 63→      resolve(false)
 64→    }
 65→    process.on('SIGINT', onSignal)
 66→    process.on('SIGTERM', onSignal)
 67→    child.on('close', (code) => {
 68→      process.off('SIGINT', onSignal)
 69→      process.off('SIGTERM', onSignal)
 70→      resolve(code === 0)
 71→    })
 72→  })
 73→}
 74→
 75→export async function checkAndPromptUpdate(): Promise<void> {
 76→  if (process.env.OPENACP_DEV_LOOP || process.env.OPENACP_SKIP_UPDATE_CHECK) return
 77→
 78→  const current = getCurrentVersion()
 79→  if (current === '0.0.0-dev') return
 80→
 81→  const latest = await getLatestVersion()
 82→  if (!latest || compareVersions(current, latest) >= 0) return
 83→
 84→  console.log(`\x1b[33mUpdate available: v${current} → v${latest}\x1b[0m`)
 85→  const { confirm } = await import('@inquirer/prompts')
 86→  const yes = await confirm({
 87→    message: 'Update now before starting?',
 88→    default: true,
 89→  })
 90→  if (yes) {
 91→    const ok = await runUpdate()
 92→    if (ok) {
 93→      console.log(`\x1b[32m✓ Updated to v${latest}. Please re-run your command.\x1b[0m`)
 94→      process.exit(0)
 95→    } else {
 96→      console.error('\x1b[31mUpdate failed. Continuing with current version.\x1b[0m')
 97→    }
 98→  }
 99→}
