 122→      if (workspace) body.workspace = workspace
 123→
 124→      const res = await apiCall(port, '/api/sessions', {
 125→        method: 'POST',
 126→        headers: { 'Content-Type': 'application/json' },
 127→        body: JSON.stringify(body),
 128→      })
 129→      const data = await res.json() as Record<string, unknown>
 130→      if (!res.ok) {
 131→        console.error(`Error: ${data.error}`)
 132→        process.exit(1)
 133→      }
 134→      console.log('Session created')
 135→      console.log(`  ID        : ${data.sessionId}`)
 136→      console.log(`  Agent     : ${data.agent}`)
 137→      console.log(`  Workspace : ${data.workspace}`)
 138→      console.log(`  Status    : ${data.status}`)
 139→
 140→    } else if (subCmd === 'cancel') {
 141→      const sessionId = args[2]
 142→      if (!sessionId) {
 143→        console.error('Usage: openacp api cancel <session-id>')
 144→        process.exit(1)
 145→      }
 146→      const res = await apiCall(port, `/api/sessions/${encodeURIComponent(sessionId)}`, {
 147→        method: 'DELETE',
 148→      })
 149→      const data = await res.json() as Record<string, unknown>
 150→      if (!res.ok) {
 151→        console.error(`Error: ${data.error}`)
 152→        process.exit(1)
 153→      }
 154→      console.log(`Session ${sessionId} cancelled`)
 155→
 156→    } else if (subCmd === 'status') {
 157→      const res = await apiCall(port, '/api/sessions')
