 528→export async function cmdConfig(args: string[] = []): Promise<void> {
 529→  const subCmd = args[1] // 'set' or undefined
 530→
 531→  if (subCmd === 'set') {
 532→    // Non-interactive: openacp config set <key> <value>
 533→    const configPath = args[2]
 534→    const configValue = args[3]
 535→    if (!configPath || configValue === undefined) {
 536→      console.error('Usage: openacp config set <path> <value>')
 537→      process.exit(1)
 538→    }
 539→
 540→    let value: unknown = configValue
 541→    try { value = JSON.parse(configValue) } catch { /* keep as string */ }
 542→
 543→    const port = readApiPort()
 544→    if (port !== null) {
 545→      // Server running — use API
 546→      const res = await apiCall(port, '/api/config', {
 547→        method: 'PATCH',
 548→        headers: { 'Content-Type': 'application/json' },
 549→        body: JSON.stringify({ path: configPath, value }),
 550→      })
 551→      const data = await res.json() as Record<string, unknown>
 552→      if (!res.ok) {
 553→        console.error(`Error: ${data.error}`)
 554→        process.exit(1)
 555→      }
 556→      console.log(`Config updated: ${configPath} = ${JSON.stringify(value)}`)
 557→      if (data.needsRestart) {
 558→        console.log('Note: restart required for this change to take effect.')
 559→      }
 560→    } else {
 561→      // Server not running — update file directly
 562→      const { ConfigManager } = await import('../core/config.js')
 563→      const cm = new ConfigManager()
 564→      if (!(await cm.exists())) {
 565→        console.error('No config found. Run "openacp" first to set up.')
 566→        process.exit(1)
 567→      }
 568→      await cm.load()
 569→      const updates = buildNestedUpdateFromPath(configPath, value)
 570→      await cm.save(updates)
 571→      console.log(`Config updated: ${configPath} = ${JSON.stringify(value)}`)
 572→    }
 573→    return
 574→  }
 575→
 576→  // Interactive editor
 577→  const { runConfigEditor } = await import('../core/config-editor.js')
 578→  const { ConfigManager } = await import('../core/config.js')
 579→  const cm = new ConfigManager()
 580→  if (!(await cm.exists())) {
 581→    console.error('No config found. Run "openacp" first to set up.')
 582→    process.exit(1)
 583→  }
 584→
 585→  const port = readApiPort()
 586→  if (port !== null) {
 587→    await runConfigEditor(cm, 'api', port)
 588→  } else {
 589→    await runConfigEditor(cm, 'file')
 590→  }
 591→}
