 593→function buildNestedUpdateFromPath(dotPath: string, value: unknown): Record<string, unknown> {
 594→  const parts = dotPath.split('.')
 595→  const result: Record<string, unknown> = {}
 596→  let target = result
 597→  for (let i = 0; i < parts.length - 1; i++) {
 598→    target[parts[i]] = {}
 599→    target = target[parts[i]] as Record<string, unknown>
 600→  }
 601→  target[parts[parts.length - 1]] = value
 602→  return result
 603→}
