 605→export async function cmdReset(): Promise<void> {
 606→  const { getStatus } = await import('../core/daemon.js')
 607→  const status = getStatus()
 608→  if (status.running) {
 609→    console.error('OpenACP is running. Stop it first: openacp stop')
 610→    process.exit(1)
 611→  }
 612→
 613→  const { confirm } = await import('@inquirer/prompts')
 614→  const yes = await confirm({
 615→    message: 'This will delete all OpenACP data (~/.openacp). You will need to set up again. Continue?',
 616→    default: false,
 617→  })
 618→  if (!yes) {
 619→    console.log('Aborted.')
 620→    return
 621→  }
 622→
 623→  const { uninstallAutoStart } = await import('../core/autostart.js')
 624→  uninstallAutoStart()
 625→
 626→  const fs = await import('node:fs')
 627→  const os = await import('node:os')
 628→  const path = await import('node:path')
 629→  const openacpDir = path.join(os.homedir(), '.openacp')
 630→  fs.rmSync(openacpDir, { recursive: true, force: true })
 631→
 632→  console.log('Reset complete. Run `openacp` to set up again.')
 633→}
