 803→  switch (subcommand) {
 804→    case "install":
 805→      return agentsInstall(args[2], args.includes("--force"));
 806→    case "uninstall":
 807→      return agentsUninstall(args[2]);
 808→    case "refresh":
 809→      return agentsRefresh();
 810→    case "info":
 811→      return agentsInfo(args[2]);
 812→    case "run":
 813→      return agentsRun(args[2], args.slice(3));
 814→    default:
 815→      return agentsList();
 816→  }
 817→}
