 869→async function agentsInstall(nameOrId: string | undefined, force: boolean): Promise<void> {
 870→  if (!nameOrId) {
 871→    console.log("\n  Usage: openacp agents install <name>");
 872→    console.log("  Run 'openacp agents' to see available agents.\n");
 873→    return;
 874→  }
 875→
 876→  const { AgentCatalog } = await import("../core/agent-catalog.js");
 877→  const catalog = new AgentCatalog();
 878→  catalog.load();
 879→  await catalog.refreshRegistryIfStale();
 880→
 881→  const progress: import("../core/types.js").InstallProgress = {
 882→    onStart(_id, name) {
 883→      process.stdout.write(`\n  ⏳ Installing ${name}...\n`);
 884→    },
 885→    onStep(step) {
 886→      process.stdout.write(`  \x1b[32m✓\x1b[0m ${step}\n`);
 887→    },
 888→    onDownloadProgress(percent) {
 889→      const filled = Math.round(percent / 5);
 890→      const empty = 20 - filled;
 891→      const bar = "█".repeat(filled) + "░".repeat(empty);
 892→      process.stdout.write(`\r  ${bar} ${String(percent).padStart(3)}%`);
 893→      if (percent >= 100) process.stdout.write("\n");
 894→    },
 895→    onSuccess(name) {
 896→      console.log(`\n  \x1b[32m✓ ${name} installed successfully!\x1b[0m\n`);
 897→    },
 898→    onError(error) {
 899→      console.log(`\n  \x1b[31m✗ ${error}\x1b[0m\n`);
 900→    },
 901→  };
 902→
 903→  const result = await catalog.install(nameOrId, progress, force);
 904→  if (!result.ok) {
 905→    process.exit(1);
 906→  }
 907→
 908→  // Show setup steps if any
 909→  if (result.setupSteps?.length) {
 910→    console.log("  \x1b[1mNext steps to get started:\x1b[0m\n");
 911→    for (const step of result.setupSteps) {
 912→      console.log(`  → ${step}`);
 913→    }
 914→    console.log(`\n  \x1b[2mRun 'openacp agents info ${result.agentKey}' for more details.\x1b[0m\n`);
 915→  }
 916→}
