1005→async function agentsRun(nameOrId: string | undefined, extraArgs: string[]): Promise<void> {
1006→  if (!nameOrId) {
1007→    console.log("\n  Usage: openacp agents run <name> [-- <args>]");
1008→    console.log("  Run the agent's CLI directly (e.g., for login or config).\n");
1009→    console.log("  Examples:");
1010→    console.log("    openacp agents run gemini -- auth login");
1011→    console.log("    openacp agents run copilot -- auth login");
1012→    console.log("    openacp agents run claude -- login\n");
1013→    return;
1014→  }
1015→
1016→  const { AgentCatalog } = await import("../core/agent-catalog.js");
1017→  const catalog = new AgentCatalog();
1018→  catalog.load();
1019→
1020→  const installed = catalog.getInstalledAgent(nameOrId);
1021→  if (!installed) {
1022→    console.log(`\n  \x1b[31m"${nameOrId}" is not installed.\x1b[0m`);
1023→    console.log(`  Install first: openacp agents install ${nameOrId}\n`);
1024→    return;
1025→  }
1026→
1027→  // Strip leading "--" separator if present
1028→  const userArgs = extraArgs[0] === "--" ? extraArgs.slice(1) : extraArgs;
1029→
1030→  const { spawnSync } = await import("node:child_process");
1031→  const command = installed.command;
1032→
1033→  // Include agent's base args (e.g., package name for npx) but strip ACP-specific flags
1034→  const acpFlags = new Set(["--acp", "acp", "--acp=true", "--experimental-skills"]);
1035→  const baseArgs: string[] = [];
1036→  for (let i = 0; i < installed.args.length; i++) {
1037→    const arg = installed.args[i]!;
1038→    // Skip standalone ACP flags
1039→    if (acpFlags.has(arg)) continue;
1040→    // Skip "--output-format acp" pair (factory-droid pattern)
1041→    if (arg === "--output-format" && installed.args[i + 1] === "acp") { i++; continue; }
1042→    // Skip "exec" subcommand used only in ACP mode (factory-droid)
1043→    if (arg === "exec" && installed.args[i + 1] === "--output-format") continue;
1044→    baseArgs.push(arg);
1045→  }
1046→  const fullArgs = [...baseArgs, ...userArgs];
1047→
1048→  console.log(`\n  Running: ${command} ${fullArgs.join(" ")}\n`);
1049→
1050→  const result = spawnSync(command, fullArgs, {
1051→    stdio: "inherit",
1052→    env: { ...process.env, ...installed.env },
1053→    cwd: process.cwd(),
1054→  });
1055→
1056→  if (result.status !== null && result.status !== 0) {
1057→    process.exit(result.status);
1058→  }
1059→}
