1061→export async function cmdDefault(command: string | undefined): Promise<void> {
1062→  const forceForeground = command === '--foreground'
1063→
1064→  // Reject unknown commands
1065→  if (command && !command.startsWith('-')) {
1066→    console.error(`Unknown command: ${command}`)
1067→    printHelp()
1068→    process.exit(1)
1069→  }
1070→
1071→  await checkAndPromptUpdate()
1072→
1073→  const { ConfigManager } = await import('../core/config.js')
1074→  const cm = new ConfigManager()
1075→
1076→  // If no config, run setup first
1077→  if (!(await cm.exists())) {
1078→    const { runSetup } = await import('../core/setup.js')
1079→    const shouldStart = await runSetup(cm)
1080→    if (!shouldStart) process.exit(0)
1081→  }
1082→
1083→  await cm.load()
1084→  const config = cm.get()
1085→
1086→  if (!forceForeground && config.runMode === 'daemon') {
1087→    const { startDaemon, getPidPath } = await import('../core/daemon.js')
1088→    const result = startDaemon(getPidPath(), config.logging.logDir)
1089→    if ('error' in result) {
1090→      console.error(result.error)
1091→      process.exit(1)
1092→    }
1093→    console.log(`OpenACP daemon started (PID ${result.pid})`)
1094→    return
1095→  }
1096→
1097→  const { markRunning } = await import('../core/daemon.js')
1098→  markRunning()
1099→  const { startServer } = await import('../main.js')
1100→  await startServer()
1101→}
